    JournalSnapshots.report.add("MAP BEFORE CHECK "+mode+" "+width+": map="+m+", inspector="+i+", frame="+JournalSnapshots.frame.getBounds());JournalSnapshots.snap("westfall-map-before-check-"+mode.name().toLowerCase(Locale.ROOT)+"-"+width);int available=JournalSnapshots.edt(()->{Container parent=map.getParent();Insets in=parent.getInsets();return parent.getWidth()-in.left-in.right;});JournalSnapshots.check(available>=840?i.x>=m.x+m.width:i.y>=m.y+m.height,"Inspector follows actual840px workspace breakpoint: available="+available+", map="+m+", inspector="+i);JournalSnapshots.check(!SwingUtilities.isDescendingFrom(legend,inspector)&&SwingUtilities.isDescendingFrom(legend,map),"Pin legend belongs below map rather than inspector");
