    JournalSnapshots.check(JournalSnapshots.edt(()->JournalSnapshots.all(inspector).stream().filter(JCheckBox.class::isInstance).map(c->((JCheckBox)c).getText()).toList().containsAll(java.util.List.of("Dungeon entrances","Flight points"))),"Inspector exposes native entrance and flight layer controls");JournalSnapshots.report.add("MAP "+mode+" "+width+": map="+m+", inspector="+i+", legend="+l+", art="+a);JournalSnapshots.snap("westfall-map-"+mode.name().toLowerCase(Locale.ROOT)+"-"+width);
